{{include reference="ReleaseNotes.Code.Change.ChangeDisplayerVelocityMacros"/}}
{{velocity}} ## Inputs: ## - $changeItems ## - $displayEditLink #set ($discard = $xwiki.ssx.use("ReleaseNotes.Code.Change.ChangeDisplayerFlow")) (% class='container col-xs-12 rn-changes-flow' %)((( #foreach ($item in $changeItems) (% class='row' %)((( ## The columns are halves only from the width at which one of them can still hold the screenshot at the size ## the gallery asks for; below that they stack, rather than shrink the screenshot to a thumbnail and the ## summary beside it to a ribbon a few words wide. (% class='col-md-6 rn-change-media' %)((( #loadChangeView($item, $displayEditLink) ## Every change gets a media block, the same way the grid displayer does: the screenshots when the change has ## any, its video when it has none, and the "no image" placeholder when it has neither. A change left with an ## empty column would otherwise be read as illustrated by the screenshot of the change displayed below it. #displayScreenshots($changeObject, true, true) ))) (% class="col-md-6 rn-change-text" %)((( ## A change with no title is given no section of its own (see #loadChangeView). #if ($title != '') === $title${displayEditLinkMarkup}===
#end ## The edit link of a change with no title reaches the summary line through a variable rather than through a ## directive closing that line: Velocity drops the newline ending a line that ends with a directive. The blank ## line that follows then keeps the link towards the change out of the paragraph the summary is rendered in. $changeSummary$summaryEditLinkMarkup
#if ($moreDetailsLinkMarkup != '') $moreDetailsLinkMarkup #end ))) )))
#end ))) {{/velocity}}

property.code:
/* The flow displayer pairs each change with its media, so the two halves of a change must start at the same
   height: a screenshot that hangs below the title it illustrates reads as belonging to the change underneath. */
.rn-changes-flow {
  /* A column may not open with the leading margin the theme gives a heading or a paragraph, which would push
     one half of a change below the other. */
  .rn-change-media > *:first-child,
  .rn-change-text > *:first-child {
    margin-top: 0;
  }

  /* Narrow enough and the two columns stack, so the text follows the media instead of sitting beside it and
     needs back the separation the margin above takes away. */
  @media (max-width: 991px) {
    .rn-change-text {
      margin-top: 20px;
    }
  }

  .rn-change-media {
    /* The gallery and the video macros both ask for a fixed width, which overflows the column when the report
       is displayed in a narrow page. */
    .gallery,
    img,
    video {
      max-width: 100%;
    }

    /* The gallery pads its box out to the fixed height it was given and centres the screenshot inside it, which
       leaves a short screenshot sitting up to a hundred pixels below the title on the other side of the row.
       Have the box hug the screenshot, and the screenshot start at the top of the box, so that a change is one
       block whatever the size of its screenshot. The height being overridden is an inline style, hence the
       !important; the maximised gallery is left alone, since it fills the viewport on purpose. */
    .xGallery:not(.maximized) {
      height: auto !important;
      /* The rows the gallery reserves for its own chrome grow with the box when the box has no fixed height,
         which would put the screenshot back below the title. */
      grid-template-rows: auto 1fr auto;

      .currentImage {
        align-self: start;
        /* The height asked of the gallery in #displayScreenshots, which no longer caps a tall screenshot now
           that the box is sized by its content. */
        max-height: 315px;
      }
    }
  }
}
